CREATE TABLE books (book VARCHAR NOT NULL PRIMARY KEY, trader VARCHAR NOT NULL, desk VARCHAR NOT NULL);
CREATE TABLE instruments (instrument VARCHAR NOT NULL PRIMARY KEY, sector VARCHAR NOT NULL, ccy VARCHAR NOT NULL,
                          beta DOUBLE NOT NULL, multiplier DOUBLE NOT NULL);
CREATE TABLE closes (instrument VARCHAR NOT NULL PRIMARY KEY, close_px DOUBLE NOT NULL);
CREATE TABLE positions (book VARCHAR NOT NULL, instrument VARCHAR NOT NULL, qty DOUBLE NOT NULL,
                        PRIMARY KEY (book, instrument));
CREATE TABLE prices (instrument VARCHAR NOT NULL PRIMARY KEY, px DOUBLE NOT NULL, ts BIGINT NOT NULL);
CREATE TABLE fx (ccy VARCHAR NOT NULL PRIMARY KEY, usd_rate DOUBLE NOT NULL, ts BIGINT NOT NULL);

CREATE TABLE subscriptions (sub_id INT NOT NULL PRIMARY KEY,
  by_desk BOOLEAN NOT NULL, by_trader BOOLEAN NOT NULL, by_book BOOLEAN NOT NULL,
  by_sector BOOLEAN NOT NULL, by_ccy BOOLEAN NOT NULL,
  f_desk VARCHAR, f_sector VARCHAR);

CREATE VIEW position_risk AS SELECT b.desk AS desk, b.trader AS trader, p.book AS book, i.sector AS sector, i.ccy AS ccy,
  'ROOT' AS root,
  p.qty * q.px * i.multiplier * f.usd_rate AS mv_usd,
  p.qty * (q.px - c.close_px) * i.multiplier * f.usd_rate AS pnl_usd,
  p.qty * q.px * i.multiplier * f.usd_rate * i.beta AS beta_delta_usd,
  q.ts AS px_ts, f.ts AS fx_ts
FROM positions AS p
JOIN instruments AS i ON p.instrument = i.instrument
JOIN books AS b ON p.book = b.book
JOIN prices AS q ON p.instrument = q.instrument
JOIN fx AS f ON i.ccy = f.ccy
JOIN closes AS c ON p.instrument = c.instrument;
CREATE MATERIALIZED VIEW live_groups AS
SELECT s.sub_id, CASE WHEN s.by_desk THEN r.desk END AS desk, CASE WHEN s.by_trader THEN r.trader END AS trader, CASE WHEN s.by_book THEN r.book END AS book, CASE WHEN s.by_sector THEN r.sector END AS sector, CASE WHEN s.by_ccy THEN r.ccy END AS ccy, SUM(r.mv_usd) AS mv_usd, SUM(r.pnl_usd) AS pnl_usd, SUM(r.beta_delta_usd) AS beta_delta_usd, COUNT(*) AS n, MAX(r.px_ts) AS last_px_ts, MAX(r.fx_ts) AS last_fx_ts
FROM position_risk r CROSS JOIN subscriptions s WHERE (s.f_desk IS NULL OR r.desk = s.f_desk) AND (s.f_sector IS NULL OR r.sector = s.f_sector) GROUP BY s.sub_id, CASE WHEN s.by_desk THEN r.desk END, CASE WHEN s.by_trader THEN r.trader END, CASE WHEN s.by_book THEN r.book END, CASE WHEN s.by_sector THEN r.sector END, CASE WHEN s.by_ccy THEN r.ccy END;
